#!/usr/bin/env node
'use strict';
/**
 * Regenerates mmc-ai-bundle.js — the browser bundle used by standalone demo mode.
 *
 * The bundle inlines the pure-JS engines from server/src/lib/mmc-ai/ so the page
 * runs with no server. Only modules with NO Node dependencies can be inlined;
 * this script asserts that before writing, so a stray `require('fs')` fails the
 * build instead of breaking the demo at runtime.
 *
 * Usage: node scripts/build-bundle.js
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.resolve(__dirname, '..');
const LIB = path.join(ROOT, 'server', 'src', 'lib', 'mmc-ai');
const OUT = path.join(ROOT, 'mmc-ai-bundle.js');

/** Modules inlined into the bundle, in dependency order. */
const MODULES = [
  'discipline-measurement-kernels',
  'discipline-layer-classifier',
  'discipline-quantity-rules',
  'dxf-takeoff',
  'bim-element-model',
  'ifc-writer',
  'glb-writer',
  'bim-link'
];

/** Public API exposed as window.MmcAi. */
const EXPORTS = {
  'discipline-layer-classifier': [
    ['classifyLayer', 'classifyLayer'],
    ['summarizeByDiscipline', 'summarizeByDiscipline'],
    ['DISCIPLINES', 'DISCIPLINES'],
    ['DISCIPLINE_LABELS', 'DISCIPLINE_LABELS']
  ],
  'discipline-quantity-rules': [
    ['proposeDisciplineQuantities', 'proposeDisciplineQuantities'],
    ['listRules', 'listRules'],
    ['RULES', 'RULES'],
    ['DEFAULTS', 'DEFAULTS']
  ],
  'discipline-measurement-kernels': [
    ['calculateMasonryWall', 'calculateMasonryWall'],
    ['calculateRectangularDuctwork', 'calculateRectangularDuctwork'],
    ['calculateRoutedServices', 'calculateRoutedServices']
  ],
  'dxf-takeoff': [
    ['takeoffDxf', 'takeoffDxf'],
    ['UNIT_TO_METRE', 'UNIT_TO_METRE']
  ],
  'bim-element-model': [
    ['buildBimElements', 'buildBimElements'],
    ['CATEGORY_TO_BIM', 'CATEGORY_TO_BIM'],
    ['DEFAULT_LEVELS', 'DEFAULT_LEVELS']
  ],
  'ifc-writer': [
    ['writeIfc', 'writeIfc'],
    ['ifcGuid', 'ifcGuid']
  ],
  'glb-writer': [
    ['writeGlb', 'writeGlb'],
    ['DISCIPLINE_COLORS', 'DISCIPLINE_COLORS']
  ],
  'bim-link': [
    ['buildLinkIndex', 'buildLinkIndex'],
    ['elementsForBoqItem', 'elementsForBoqItem'],
    ['boqItemsForElement', 'boqItemsForElement']
  ]
};

const NODE_ONLY = /\brequire\(\s*['"](?:fs|path|crypto|node:|child_process|os|http|https|stream|zlib|util|events|url|buffer)['"]\s*\)/;

function readModule(name) {
  const file = path.join(LIB, name + '.js');
  const src = fs.readFileSync(file, 'utf8');
  if (NODE_ONLY.test(src)) {
    throw new Error('Module "' + name + '" uses a Node-only API and cannot be bundled for the browser.');
  }
  return src;
}

function build() {
  const parts = [];
  parts.push('/* MMC AI engines — browser bundle (auto-generated by scripts/build-bundle.js).');
  parts.push(' * Source: server/src/lib/mmc-ai/*.js (pure JS, no Node APIs).');
  parts.push(' * Exposed as window.MmcAi. Do not edit by hand — run the build script.');
  parts.push(' */');
  parts.push('(function() {');
  parts.push("  'use strict';");
  parts.push('  const __mods = {};');
  parts.push('  function require(p) { return __mods[p] || {}; }');
  parts.push('');

  for (const name of MODULES) {
    const src = readModule(name);
    parts.push('  // ===== ' + name + '.js =====');
    parts.push('  (function() {');
    parts.push('    const module = { exports: {} };');
    parts.push('    const exports = module.exports;');
    parts.push(src);
    parts.push("    __mods['./" + name + "'] = module.exports;");
    parts.push('  })();');
    parts.push('');
  }

  parts.push('  // Expose the public API used by the page + demo backend');
  parts.push('  window.MmcAi = {');
  const lines = [];
  for (const [mod, pairs] of Object.entries(EXPORTS)) {
    lines.push('    // ' + mod);
    for (const [key, prop] of pairs) {
      lines.push('    ' + key + ': ' + "require('./" + mod + "')." + prop + ',');
    }
  }
  lines.push('    // Utility');
  lines.push('    _require: require');
  parts.push(lines.join('\n'));
  parts.push('  };');
  parts.push('})();');
  parts.push('');

  fs.writeFileSync(OUT, parts.join('\n'), 'utf8');
  return OUT;
}

if (require.main === module) {
  const out = build();
  const size = fs.statSync(out).size;
  console.log('Wrote ' + path.relative(ROOT, out) + ' (' + size + ' bytes, ' + MODULES.length + ' modules)');
}

module.exports = { build, MODULES, EXPORTS };
